-- Plano e cobrança (decisão do fundador, 2026-10-17): os cartões não citam mais "mais usuários: R$ 49,90" e o limite de IA é um só,
-- por número de mensagens (Renata por texto, Renata por voz e WhatsApp somados), sem minutos de voz à parte. Já aplicado no banco.
update public.planos set itens = array['Pacientes, prontuário e agenda','Anamnese com assinatura digital','Financeiro, estoque e CRM de leads','WhatsApp da clínica no sistema (1 número)','2 usuários incluídos e até 3 profissionais','Saluteflix e Salute Cast'], atualizado_em = now() where codigo = 'inicial';
update public.planos set itens = array['Tudo do plano Inicial','Renata IA por texto e por voz dentro do sistema','1.500 mensagens de IA por mês (Renata por texto, por voz e WhatsApp somados)','Lembretes automáticos de consulta','Envio automático de anamnese e documentos','2 usuários incluídos e até 6 profissionais'], atualizado_em = now() where codigo = 'assistente';
update public.planos set itens = array['Tudo do plano Assistente','IA atendendo no WhatsApp 24 horas','10.000 mensagens de IA por mês (Renata por texto, por voz e WhatsApp somados)','Agendamento, confirmação e follow-up automáticos','CRM que anda sozinho','2 usuários incluídos e até 10 profissionais'], atualizado_em = now() where codigo = 'iapro';

-- Correção do fundador (2026-10-17): usuários incluídos valem para equipe ou profissionais, sem limite separado de profissionais:
-- Inicial 2, Assistente 2, IA Pro 4; cada usuário a mais é cobrado à parte.
update public.planos set limite_usuarios = 2, itens = array['Pacientes, prontuário e agenda','Anamnese com assinatura digital','Financeiro, estoque e CRM de leads','WhatsApp da clínica no sistema (1 número)','2 usuários incluídos (equipe ou profissionais)','Saluteflix e Salute Cast'], atualizado_em = now() where codigo = 'inicial';
update public.planos set limite_usuarios = 2, itens = array['Tudo do plano Inicial','Renata IA por texto e por voz dentro do sistema','1.500 mensagens de IA por mês (Renata por texto, por voz e WhatsApp somados)','Lembretes automáticos de consulta','Envio automático de anamnese e documentos','2 usuários incluídos (equipe ou profissionais)'], atualizado_em = now() where codigo = 'assistente';
update public.planos set limite_usuarios = 4, itens = array['Tudo do plano Assistente','IA atendendo no WhatsApp 24 horas','10.000 mensagens de IA por mês (Renata por texto, por voz e WhatsApp somados)','Agendamento, confirmação e follow-up automáticos','CRM que anda sozinho','4 usuários incluídos (equipe ou profissionais)'], atualizado_em = now() where codigo = 'iapro';
